        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        background:
          radial-gradient(circle at 20% 10%, rgb(14 165 233 / 0.28), transparent 32rem),
          radial-gradient(circle at 80% 0%, rgb(244 63 94 / 0.18), transparent 28rem),
          linear-gradient(135deg, #05070d 0%, var(--bg) 48%, #101827 100%);
        color: var(--text);
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
