        display: grid;
        gap: 1.35rem;
        padding: clamp(1.25rem, 4vw, 2.25rem);
      }

      .eyebrow {
        margin: 0 0 0.35rem;
        color: var(--accent);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.16em;
        text-transform: uppercase;
