      .status-message {
        min-height: 1.5rem;
        margin: 0;
        color: var(--accent);
        font-weight: 700;
      }

      .deleted-state {
        border: 1px dashed var(--line);
        border-radius: 1.25rem;
        background: rgb(15 23 42 / 0.68);
        padding: 2rem;
        text-align: center;
