        background: rgb(2 6 23 / 0.78);
        backdrop-filter: blur(6px);
      }

      .dialog-panel {
        display: grid;
        gap: 1rem;
        padding: clamp(1.25rem, 5vw, 2rem);
      }

      .dialog-icon {
        display: grid;
        width: 3rem;
        height: 3rem;
        place-items: center;
        border-radius: 1rem;
        background: rgb(244 63 94 / 0.16);
        color: #fecdd3;
        font-size: 1.45rem;
