        --accent: #7dd3fc;
        --danger: #fb7185;
        --danger-strong: #e11d48;
        --shadow: 0 24px 80px rgb(0 0 0 / 0.55);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        background:
          radial-gradient(circle at 20% 10%, rgb(14 165 233 / 0.28), transparent 32rem),
          radial-gradient(circle at 80% 0%, rgb(244 63 94 / 0.18), transparent 28rem),
          linear-gradient(135deg, #05070d 0%, var(--bg) 48%, #101827 100%);
        color: var(--text);
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      .skip-link {
        position: fixed;
        inset-block-start: 1rem;
        inset-inline-start: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        background: var(--text);
        color: var(--bg);
        padding: 0.75rem 1rem;
        font-weight: 700;
        transition: transform 160ms ease;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      main {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: clamp(1rem, 3vw, 3rem);
      }

      .preview-card {
        width: min(100%, 54rem);
        overflow: hidden;
        border: 1px solid rgb(255 255 255 / 0.12);
        border-radius: 1.75rem;
        background: rgb(17 24 39 / 0.82);
        box-shadow: var(--shadow);
        backdrop-filter: blur(22px);
      }

      .preview-image {
        display: block;
        width: 100%;
        aspect-ratio: 16 / 10;
        object-fit: cover;
        background: #111827;
      }

      .preview-content {
        display: grid;
        gap: 1.35rem;
        padding: clamp(1.25rem, 4vw, 2.25rem);
      }

      .eyebrow {
        margin: 0 0 0.35rem;
        color: var(--accent);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.16em;
        text-transform: uppercase;
      }

      h1,
      h2,
      p {
        margin-block-start: 0;
      }

      h1 {
        margin-block-end: 0.45rem;
        font-size: clamp(2rem, 6vw, 4.5rem);
        line-height: 0.95;
        letter-spacing: -0.06em;
      }

      .description {
        max-width: 42rem;
        margin-block-end: 0;
        color: var(--muted);
        font-size: 1.03rem;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.85rem;
      }

      button {
        min-height: 44px;
        border: 0;
        border-radius: 999px;
        padding: 0.8rem 1.1rem;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
      }

      button:focus-visible,
      dialog:focus-visible,
      .skip-link:focus-visible,
      .status-message:focus-visible {
        outline: 3px solid var(--accent);
        outline-offset: 4px;
      }

      .trigger {
        background: linear-gradient(135deg, var(--danger), var(--danger-strong));
        color: white;
        box-shadow: 0 12px 28px rgb(225 29 72 / 0.35);
      }

      .trigger:hover {
        filter: brightness(1.08);
      }

      .secondary-action {
        border: 1px solid var(--line);
        background: var(--surface-strong);
        color: var(--text);
      }

      .danger-action {
        background: var(--danger-strong);
        color: white;
      }

      .status-message {
        min-height: 1.5rem;
        margin: 0;
        color: var(--accent);
        font-weight: 700;
      }

      .deleted-state {
        border: 1px dashed var(--line);
        border-radius: 1.25rem;
        background: rgb(15 23 42 / 0.68);
        padding: 2rem;
        text-align: center;
      }

      [hidden] {
        display: none !important;
      }

      dialog {
        width: min(92vw, 30rem);
        border: 1px solid rgb(255 255 255 / 0.16);
        border-radius: 1.4rem;
        background: linear-gradient(145deg, #151c2f, #0e1422);
        color: var(--text);
        box-shadow: var(--shadow);
        padding: 0;
      }

      dialog::backdrop {
        background: rgb(2 6 23 / 0.78);
        backdrop-filter: blur(6px);
      }

      .dialog-panel {
        display: grid;
        gap: 1rem;
        padding: clamp(1.25rem, 5vw, 2rem);
      }

      .dialog-icon {
        display: grid;
        width: 3rem;
        height: 3rem;
        place-items: center;
        border-radius: 1rem;
        background: rgb(244 63 94 / 0.16);
        color: #fecdd3;
        font-size: 1.45rem;
      }

      h2 {
        margin-block-end: 0;
        font-size: clamp(1.45rem, 5vw, 2rem);
        line-height: 1.05;
        letter-spacing: -0.035em;
      }

      .dialog-panel p {
        margin-block-end: 0;
        color: var(--muted);
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: 0.75rem;
        margin-block-start: 0.4rem;
      }

      @media (max-width: 32rem) {
        .actions,
        .dialog-actions {
          flex-direction: column;
        }

        button {
          width: 100%;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
        }
      }

      @media (forced-colors: active) {
        .preview-card,
        dialog,
        .deleted-state {
          border: 1px solid CanvasText;
        }

        button,
        .trigger,
        .secondary-action,
        .danger-action {
          border: 1px solid ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content" tabindex="-1">
      <article class="preview-card" aria-labelledby="page-title">
        <div id="image-preview">
          <img
            class="preview-image"
            src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=80"
            alt="Sunlit cabin beside a lake surrounded by evergreen trees"
          >

          <div class="preview-content">
            <div>
              <p class="eyebrow">Library preview</p>
              <h1 id="page-title">Mountain Lake Cabin</h1>
              <p class="description">
                Review the selected image before making changes to your library.
                Deleting it will remove this image from your saved collection.
              </p>
            </div>

            <div class="actions">
              <button class="trigger" type="button" aria-haspopup="dialog">
                Delete image
              </button>
            </div>
          </div>
        </div>

        <div id="deleted-state" class="deleted-state" hidden>
          <p class="eyebrow">Image removed</p>
          <h1>Mountain Lake Cabin was deleted</h1>
          <p class="description">
            The image has been removed from your library.
          </p>
        </div>

        <p id="status-message" class="status-message" tabindex="-1" aria-live="polite"></p>
      </article>
    </main>

    <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
      <form class="dialog-panel" method="dialog">
        <span class="dialog-icon" aria-hidden="true">!</span>
        <div>
          <h2 id="dialog-title">Delete this image?</h2>
          <p id="dialog-description">
            This will permanently remove "Mountain Lake Cabin" from your library.
            This action cannot be undone.
          </p>
        </div>
        <div class="dialog-actions">
          <button class="secondary-action" type="submit" value="cancel" data-cancel>
            Cancel
          </button>
          <button class="danger-action" type="submit" value="delete">
            Delete image
          </button>
        </div>
      </form>
    </dialog>

    <script>
      const dialog = document.querySelector("#delete-dialog");
      const trigger = document.querySelector(".trigger");
      const cancelButton = dialog.querySelector("[data-cancel]");
      const imagePreview = document.querySelector("#image-preview");
      const deletedState = document.querySelector("#deleted-state");
      const statusMessage = document.querySelector("#status-message");

      trigger.addEventListener("click", () => {
        dialog.showModal();
        cancelButton.focus();
      });

      dialog.addEventListener("close", () => {
        if (dialog.returnValue !== "delete") {
          return;
        }

        imagePreview.hidden = true;
        deletedState.hidden = false;
        statusMessage.textContent = "Image deleted from your library.";
        statusMessage.focus();
      });
    </script>
  </body>
</html>
