     <a class="skip-link" href="#main-content">Skip to main content</a>

     <main id="main-content" tabindex="-1">
       <article class="preview-card">
         <div id="image-preview">
           <img
             class="preview-image"
             src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&amp;fit=crop&amp;w=1400&amp;q=80"
             alt="Sunlit cabin beside a lake surrounded by evergreen trees"
           >

           <div class="preview-content">
             <div>
               <p class="eyebrow">Library preview</p>
               <h1 id="page-title">Mountain Lake Cabin</h1>
               <p class="description">
                 Review the selected image before making changes to your library.
                 Deleting it will remove this image from your saved collection.
               </p>
             </div>

             <div class="actions">
               <button class="trigger" type="button" aria-haspopup="dialog">
                 Delete image
               </button>
             </div>
           </div>
         </div>

         <div id="deleted-state" class="deleted-state" hidden>
           <p class="eyebrow">Image removed</p>
           <h1>Mountain Lake Cabin was deleted</h1>
           <p class="description">
             The image has been removed from your library.
           </p>
         </div>

         <p id="status-message" class="status-message" tabindex="-1" aria-live="polite"></p>
       </article>
     </main>

     <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
       <form class="dialog-panel" method="dialog">
         <span class="dialog-icon" aria-hidden="true">!</span>
         <div>
           <h2 id="dialog-title">Delete this image?</h2>
           <p id="dialog-description">
             This will permanently remove "Mountain Lake Cabin" from your library.
             This action cannot be undone.
           </p>
         </div>
         <div class="dialog-actions">
           <button class="secondary-action" type="submit" value="cancel" data-cancel>
             Cancel
           </button>
           <button class="danger-action" type="submit" value="delete">
             Delete image
           </button>
         </div>
       </form>
     </dialog>

     <script>
       const dialog = document.querySelector("#delete-dialog");
       const trigger = document.querySelector(".trigger");
       const cancelButton = dialog.querySelector("[data-cancel]");
       const imagePreview = document.querySelector("#image-preview");
       const deletedState = document.querySelector("#deleted-state");
       const statusMessage = document.querySelector("#status-message");

       trigger.addEventListener("click", () => {
         dialog.showModal();
         cancelButton.focus();
       });

       dialog.addEventListener("close", () => {
         if (dialog.returnValue !== "delete") {
           return;
         }

         imagePreview.hidden = true;
         deletedState.hidden = false;
         statusMessage.textContent = "Image deleted from your library.";
         statusMessage.focus();
       });
     </script>
   </body>
 </html>

